#[derive(Parser, Debug)]
#[command(name = "zoxide")]
#[command(author = "Ajeet D'Souza <98ajeet@gmail.com>")]
#[command(version = "0.9.9")]
#[command(about = "A smarter cd command for your terminal", long_about = None)]
struct Cli {
    #[command(subcommand)]
    command: Option<Commands>,
    #[arg(short, long, action = clap::ArgAction::Help)]
    help: Option<bool>,
    #[arg(short = 'V', long, action = clap::ArgAction::Help)]
    version: Option<bool>,
}

#[derive(Subcommand, Debug)]
enum Commands {
    Add {
        #[arg(short = 's', long)]
        score: Option<u32>,
    },
    Edit,
    Import {
        #[arg(long)]
        from: ImportSource,
        path: PathBuf,
    },
    Init {
        shell: Shell,
        #[arg(long)]
        no_cmd: bool,
        #[arg(long, default_value = "z")]
        cmd: String,
        #[arg(long, default_value = "pwd")]
        hook: Hook,
    },
    Query {
        #[arg(short = 'a', long)]
        all: bool,
        #[arg(short = 'i', long)]
        interactive: bool,
        #[arg(short = 'l', long)]
        list: bool,
        #[arg(short = 's', long)]
        score: bool,
        #[arg(long)]
        exclude: Option<String>,
        #[arg(long)]
        base_dir: Option<String>,
    },
    Remove {
        path: String,
    },
}
```

